def gen(rng):
    def steps(n):
        k = 0
        while True:
            t = str(n)
            if t == t[::-1]:
                return k, n
            n += int(t[::-1])
            k += 1
            if k > 1000 or n > 10**18:
                return None
    def ok(n):
        return steps(n) is not None
    tests = []
    base = [87, 19, 12321, 1, 9, 10, 11, 12, 89, 120, 100, 1000, 10**9, 999999999, 123454321, 100000001, 98, 79, 69, 5280, 1291, 4994]
    for n in base:
        if 1 <= n <= 10**9 and ok(n):
            tests.append(str(n))
    for hi in (30, 100, 1000, 10**5):
        c = 0
        while c < 4:
            n = rng.randint(1, hi)
            if ok(n):
                tests.append(str(n))
                c += 1
    # large inputs with long chains
    best = []
    tries = 0
    while len(best) < 4 and tries < 20000:
        tries += 1
        n = rng.randint(9 * 10**8, 10**9)
        r = steps(n)
        if r is not None and r[0] >= 8:
            best.append(n)
    for n in best:
        tests.append(str(n))
    c = 0
    while c < 3:
        n = rng.randint(5 * 10**8, 10**9)
        if ok(n):
            tests.append(str(n))
            c += 1
    return tests

